CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, email text, phone text, password_hash text, identity_public_key text, account_status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name text NOT NULL, avatar_url text, bio text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_token_hash text NOT NULL, device_fingerprint text, device_os text, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_user_sessions_user ON user_sessions(user_id);
CREATE TABLE chat_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_type text NOT NULL, title text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_participants (room_id uuid NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'MEMBER', joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,user_id));
CREATE INDEX idx_chat_participants_user ON chat_participants(user_id);
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), encrypted_payload text NOT NULL, content_type text NOT NULL DEFAULT 'TEXT', client_message_id text NOT NULL, ephemeral boolean NOT NULL DEFAULT false, burn_duration_seconds integer, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_messages_room_created ON messages(room_id,created_at DESC);
CREATE INDEX idx_messages_sender ON messages(sender_id);
CREATE UNIQUE INDEX idx_messages_sender_client_id ON messages(sender_id,client_message_id);
CREATE TABLE blocked_users (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,blocked_user_id), CONSTRAINT blocked_users_not_self CHECK(user_id<>blocked_user_id));
CREATE TABLE notification_settings (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, push_enabled boolean NOT NULL DEFAULT true, message_notifications boolean NOT NULL DEFAULT true, call_notifications boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, currency_code text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES wallet_accounts(id) ON DELETE CASCADE, entry_type text NOT NULL, amount_minor bigint NOT NULL, reference_type text, reference_id text, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
